fn split_str(s: Str, delimiter: Str) -> Vec<Str> {
    let mut result = vec()
    let mut current = ""
    for c in chars(s) {
        if c == delimiter {
            result = push(result, current)
            current = ""
        } else {
            current = concat(current, c)
        }
    }
    push(result, current)
}

fn main() {
    let total = 0
    let count = 0
    for c in chars("a1b22") {
        let n = unwrap_or(parse_int(c), -1)
        if n >= 0 {
            total += n
            count += 1
        }
    }
    print(total)
    print(count)
}

